    if(!isFinite(v))return String(v)+" "+unit;
    var a=Math.abs(v),sg=v<0?"-":"";
    var P=[[1e9,"G"],[1e6,"M"],[1e3,"k"],[1,""],[1e-3,"m"],[1e-6,"\u00b5"],[1e-9,"n"],[1e-12,"p"]];
    if(a===0)return"0 "+unit;
    for(var i=0;i<P.length;i++){if(a>=P[i][0]*0.9999)return sg+parseFloat((a/P[i][0]).toPrecision(5))+" "+P[i][1]+unit;}
    return sg+a.toExponential(3)+" "+unit;
