// ── MHO98 Live Measurements ──────────────────────────────────────────────
// Continuous Vpp/Vrms/Freq/Period/Vmax/Vmin readout for one channel.
// STOP: click the red Stop button in EEZ (toolbar/script runner) at any time.
// A bounded MAX_READS guarantees the script ends on its own as a safety net.
const CH       = 1;       // channel to measure
const MAX_READS = 600;    // safety cap (~3 min @ 300ms); set higher if needed
const INTERVAL  = 300;    // ms between updates

const ITEMS  = ["VPP","VRMS","FREQuency","PERiod","VMAX","VMIN"];
const LABELS = ["Vpp","Vrms","Freq","Period","Vmax","Vmin"];
const UNITS  = ["V","V","Hz","s","V","V"];

await resetAndAcquire();
var toast = notify.info("MHO98 Live Meas CH"+CH+" — click Stop to end", {autoClose:false, position:"bottom-right"});
try {
    connection.command(":RUN");
    var i=0;
    while (i < MAX_READS) {
        if (session.isStopped) break;          // checked every loop, before any query
        var parts=[];
        for (var m=0; m<ITEMS.length; m++) {
            if (session.isStopped) break;       // also check between queries
            var v = parseFloat(qts(await connection.query(":MEASure:ITEM? "+ITEMS[m]+",CHANnel"+CH)));
            parts.push(LABELS[m]+" "+(Math.abs(v)>9e36?"--":siFmt(v,UNITS[m])));
        }
        if (session.isStopped) break;
        notify.update(toast,{render:"CH"+CH+"  ["+(i+1)+"/"+MAX_READS+"]  \u2502  "+parts.join("   "),autoClose:false});
        i++;
        // Sleep in short slices so Stop is honoured quickly
        for (var w=0; w<INTERVAL/50 && !session.isStopped; w++) {
            await new Promise(r=>setTimeout(r,50));
        }
    }
    notify.update(toast,{render:"Live Meas stopped after "+i+" reads (CH"+CH+")",autoClose:3000});
} catch(e) {
    notify.update(toast,{render:"Live meas failed: "+e.message,autoClose:5000,type:"error"});
} finally {
    connection.release();
}

