// ── MHO98 Vertical Setup ─────────────────────────────────────────────────
// Configure a channel: On/Off, Coupling, Impedance, Probe, Scale, Offset,
// Unit, BW Limit, Invert, Fine (vernier).
await resetAndAcquire();
try {
    // Read current state of CH1 to prefill
    var ch = 1;
    function rd(c){ return qts(connection.query(c)); }

    var vals = await input({
        title: "MHO98 — Vertical (Channel) Setup",
        size: "medium",
        fields: [
            { name:"channel", displayName:"Channel", type:"enum",
              enumItems:[{id:"1",label:"CH1"},{id:"2",label:"CH2"},{id:"3",label:"CH3"},{id:"4",label:"CH4"}] },
            { name:"display", displayName:"Display", type:"enum",
              enumItems:[{id:"ON",label:"On"},{id:"OFF",label:"Off"}] },
            { name:"coupling", displayName:"Coupling", type:"enum",
              enumItems:[{id:"DC",label:"DC"},{id:"AC",label:"AC"},{id:"GND",label:"GND"}] },
            { name:"impedance", displayName:"Impedance", type:"enum",
              enumItems:[{id:"ONEMeg",label:"1 M\u03a9"},{id:"FIFTy",label:"50 \u03a9"}] },
            { name:"probe", displayName:"Probe Ratio", type:"enum",
              enumItems:[{id:"0.01",label:"0.01X"},{id:"0.1",label:"0.1X"},{id:"1",label:"1X"},{id:"10",label:"10X"},{id:"100",label:"100X"},{id:"1000",label:"1000X"}] },
            { name:"scale", displayName:"Scale (V/div)", type:"number", unit:"voltage" },
            { name:"offset", displayName:"Offset (V)", type:"number", unit:"voltage" },
            { name:"unit", displayName:"Unit", type:"enum",
              enumItems:[{id:"VOLTage",label:"Volt"},{id:"AMPere",label:"Amp"},{id:"WATT",label:"Watt"},{id:"UNKNown",label:"Unknown"}] },
            { name:"bwlimit", displayName:"BW Limit", type:"enum",
              enumItems:[{id:"OFF",label:"Off (Full)"},{id:"20M",label:"20 MHz"},{id:"250M",label:"250 MHz"}] },
            { name:"invert", displayName:"Invert", type:"boolean" },
            { name:"vernier", displayName:"Fine (Vernier)", type:"boolean" }
        ]
    }, {
        channel:"1", display:"ON", coupling:"DC", impedance:"ONEMeg",
        probe:"1", scale:0.05, offset:0, unit:"VOLTage", bwlimit:"OFF",
        invert:false, vernier:false
    });

    if (!vals) { notify.info("Vertical setup cancelled"); connection.release(); return; }

    var c = vals.channel;
    connection.command(":CHANnel"+c+":DISPlay "+vals.display);
    connection.command(":CHANnel"+c+":COUPling "+vals.coupling);
    connection.command(":CHANnel"+c+":IMPedance "+vals.impedance);
    connection.command(":CHANnel"+c+":PROBe "+vals.probe);
    connection.command(":CHANnel"+c+":SCALe "+vals.scale);
    connection.command(":CHANnel"+c+":OFFSet "+vals.offset);
    connection.command(":CHANnel"+c+":UNITs "+vals.unit);
    connection.command(":CHANnel"+c+":BWLimit "+vals.bwlimit);
    connection.command(":CHANnel"+c+":INVert "+(vals.invert?"ON":"OFF"));
    connection.command(":CHANnel"+c+":VERNier "+(vals.vernier?"ON":"OFF"));
    await new Promise(r=>setTimeout(r,150));

    var sc = parseFloat(qts(await connection.query(":CHANnel"+c+":SCALe?")));
    var of = parseFloat(qts(await connection.query(":CHANnel"+c+":OFFSet?")));
    notify.info("CH"+c+" set: "+vals.display+" "+vals.coupling+" "+siFmt(sc,"V")+"/div offset "+siFmt(of,"V")+" probe "+vals.probe+"X BW "+vals.bwlimit);
} catch(e) {
    notify.error("Vertical setup failed: "+e.message);
} finally {
    connection.release();
}

