// ── MHO98 Trigger Setup ──────────────────────────────────────────────────
// Edge trigger: Source, Slope, Level, Sweep, Coupling, Holdoff, Noise Reject.
await resetAndAcquire();
try {
    var vals = await input({
        title: "MHO98 — Trigger Setup (Edge)",
        size: "medium",
        fields: [
            { name:"source", displayName:"Source", type:"enum",
              enumItems:[{id:"CHANnel1",label:"CH1"},{id:"CHANnel2",label:"CH2"},{id:"CHANnel3",label:"CH3"},{id:"CHANnel4",label:"CH4"},{id:"AC",label:"AC Line"}] },
            { name:"slope", displayName:"Slope", type:"enum",
              enumItems:[{id:"POSitive",label:"Rising \u2197"},{id:"NEGative",label:"Falling \u2198"},{id:"RFALl",label:"Either \u2195"}] },
            { name:"level", displayName:"Level (V)", type:"number", unit:"voltage" },
