            (f.addr === null ? "(empty)" :
                "0x" + hex2(f.addr) + " " + f.rw + (data.length ? " " + data.join(" ") : "")) +
            (f.complete ? "" : " (no STOP)"));
    }
    if (r.frames.length > 12) parts.push("... +" + (r.frames.length - 12) + " more");
    if (r.warnings.length) parts.push("[!] " + r.warnings[0]);
    return parts.join(SEP);
}

/** Multi-line I2C report. */
function i2cReport(r) {
    const L = ["I2C decode"];
    L.push("SDA " + r.thresholds.sda.min.toFixed(2) + "V.." + r.thresholds.sda.max.toFixed(2) +
        "V   SCL " + r.thresholds.scl.min.toFixed(2) + "V.." + r.thresholds.scl.max.toFixed(2) + "V");
    L.push("");
    if (!r.frames.length) {
        r.warnings.forEach(w => L.push("! " + w));
        return L.join("\n");
    }
    let i = 1;
    for (const f of r.frames) {
        if (f.addr === null) {
            L.push("#" + (i++) + " @" + fmtTimeShort(f.tStart) + "  (START..STOP, no data)");
            continue;
        }
        const data = f.bytes.slice(1);
        L.push("#" + (i++) + " @" + fmtTimeShort(f.tStart) + "  addr 0x" + hex2(f.addr) +
            " " + f.rw + (f.repeatedStarts ? "  (+" + f.repeatedStarts + " repeated START)" : "") +
            (f.complete ? "" : "  [no STOP]"));
        if (data.length) L.push("    data: " +
            data.map(b => "0x" + hex2(b.value) + (b.ack ? "" : "(NACK)")).join(" "));
    }
    if (r.warnings.length) {
        L.push("");
        r.warnings.forEach(w => L.push("! " + w));
    }
    return L.join("\n");
}

/** One-line summary of a DS248x decode. */
function ds248xSummary(i2c, ds) {
    if (!ds.ops.length) {
        return ds.warnings.length ? ds.warnings[0] :
            (i2c.frames.length ? "no DS248x traffic in " + i2c.frames.length + " I2C frames"
                               : "no I2C frames");
    }
    const parts = [ds.ops.length + " DS248x op" + (ds.ops.length === 1 ? "" : "s")];
    for (const o of ds.ops.slice(0, 12))
        parts.push("@" + fmtTimeShort(o.t) + " " + o.text);
    if (ds.ops.length > 12) parts.push("... +" + (ds.ops.length - 12) + " more");
    if (ds.warnings.length) parts.push("[!] " + ds.warnings[0]);
    return parts.join(SEP);
}

/** Multi-line DS248x report. */
function ds248xReport(i2c, ds) {
    const L = ["DS248x (I2C-to-1-Wire bridge) decode"];
    L.push(i2c.frames.length + " I2C frames, " + ds.ops.length + " DS248x operations");
    if (ds.addressesSeen.length)
        L.push("I2C addresses seen: " + ds.addressesSeen.map(a => "0x" + hex2(a)).join(" "));
    L.push("");
    let i = 1;
    for (const o of ds.ops)
        L.push("#" + (i++) + " @" + fmtTimeShort(o.t) + "  [0x" + hex2(o.addr) + "] " + o.text);
    const all = i2c.warnings.concat(ds.warnings);
    if (all.length) {
        L.push("");
        all.forEach(w => L.push("! " + w));
    }
    return L.join("\n");
}

module.exports = {
    oneWireSummary, oneWireReport, i2cSummary, i2cReport,
    ds248xSummary, ds248xReport, fmtTimeShort
};

