// ---------------------------------------------------------------------------
// Capture-and-decode. Pulls the RAW deep-memory record for the selected
// channels at 12-bit (WORD) fidelity, then decodes it in-place and shows a
// full multi-line report.
//
// To stop: click "Scripts" in the left nav -- the Stop button lives in that
// section's toolbar (verified in app.tsx: only the selected nav item's toolbar
// buttons are rendered). This toast is positioned bottom-right so it no longer
// covers the button.
// ---------------------------------------------------------------------------
if (!document.getElementById('ksstech-decode-toast-fix')) {
    var _s = document.createElement('style');
    _s.id = 'ksstech-decode-toast-fix';
    _s.textContent = '.Toastify__toast-body{white-space:pre-line;font-family:monospace}';
    document.head.appendChild(_s);
}
function qts(r){
    if(r===null||r===undefined)return"";
    if(typeof r==="string")return r;
    if(typeof r==="number")return String(r);
    if(r.data){var t=new TextDecoder().decode(new Uint8Array(r.data));return t.charAt(0)==='#'?t.substring(2+parseInt(t.charAt(1))):t;}
    return String(r);
}
var MAX_DECODE_PTS = 2000000;   // 2 Mpts/channel is ample for protocol work
var CHUNK = 125000;

// Set the waveform read window, verifying it took. The MHO98 validates
// STARt/STOP against the CURRENT memory depth: if a previous capture left the
// window beyond a now-smaller depth, every set is rejected (-200) and the
// window stays stuck, silently returning the wrong samples. Verified on
// hardware 2026-08-12.
async function setWindow(a, b) {
    connection.command(":WAVeform:STOP " + b);
    connection.command(":WAVeform:STARt " + a);
    var ga = parseInt(qts(await connection.query(":WAVeform:STARt?")));
    var gb = parseInt(qts(await connection.query(":WAVeform:STOP?")));
    if (ga === a && gb === b) return true;
    // Recover: widen the depth so the stale window is in range, collapse it.
    var saved = qts(await connection.query(":ACQuire:MDEPth?"));
    connection.command(":ACQuire:MDEPth 100M");
    await new Promise(r=>setTimeout(r,400));
    connection.command(":WAVeform:STARt 1");
    connection.command(":WAVeform:STOP 1000");
    connection.command(":ACQuire:MDEPth " + parseInt(parseFloat(saved)));
    await new Promise(r=>setTimeout(r,400));
    connection.command(":WAVeform:STOP " + b);
    connection.command(":WAVeform:STARt " + a);
    ga = parseInt(qts(await connection.query(":WAVeform:STARt?")));
    gb = parseInt(qts(await connection.query(":WAVeform:STOP?")));
    return ga === a && gb === b;
}

async function captureChannel(ch, npts, toast, label) {
    connection.command(":WAVeform:SOURce CHANnel" + ch);
    connection.command(":WAVeform:MODE RAW");
    connection.command(":WAVeform:FORMat WORD");
    if (!await setWindow(1, npts))
        throw new Error("Could not set the waveform window for CH" + ch +
            " -- try a fresh single acquisition first");
    await new Promise(r=>setTimeout(r,120));
    var pre = qts(await connection.query(":WAVeform:PREamble?")).trim().split(",");
    var yinc = parseFloat(pre[7]), yor = parseFloat(pre[8]), yref = parseFloat(pre[9]);
    var out = new Float32Array(npts), got = 0;
    var nChunks = Math.ceil(npts / CHUNK);
    for (var j = 0; j < nChunks; j++) {
        var a = j*CHUNK + 1, b = Math.min((j+1)*CHUNK, npts);
        notify.update(toast, {render: label + ": CH" + ch + " chunk " + (j+1) + "/" + nChunks,
            autoClose:false});
        if (!await setWindow(a, b)) throw new Error("window " + a + ".." + b + " rejected");
        var wf = await connection.query(":WAVeform:DATA?");
        if (wf && wf.data) {
            var by = new Uint8Array(wf.data);
            var n = Math.floor(by.length/2);
            for (var i2 = 0; i2 < n && got < npts; i2++, got++)
                out[got] = ((by[2*i2] | (by[2*i2+1]<<8)) - yor - yref) * yinc;
            if (wf.deleteLog) wf.deleteLog();
        }
    }
    return {volts: out, n: got};
}

async function prepareCapture(toast, label) {
    connection.command(":STOP");
    await new Promise(r=>setTimeout(r,200));
    var depth = parseFloat(qts(await connection.query(":ACQuire:MDEPth?")));
    var srate = parseFloat(qts(await connection.query(":ACQuire:SRATe?")));
    if (!isFinite(depth) || depth < 1) throw new Error("bad :ACQuire:MDEPth? reply");
    var npts = Math.min(depth, MAX_DECODE_PTS);
    return {npts: npts, srate: srate, depth: depth};
}

var i2c = require("i2c");
var ds = require("ds248x");
var rep = require("report");

var SDA_CH = 1;   // SDA
var SCL_CH = 2;   // SCL

await connection.acquire(true);
var toast = notify.info("DS248x decode: capturing...",
    {autoClose:false, position:"bottom-right"});
try {
    var info = await prepareCapture(toast, "DS248x");
    var a = await captureChannel(SDA_CH, info.npts, toast, "SDA");
    var b = await captureChannel(SCL_CH, info.npts, toast, "SCL");
    var n = Math.min(a.n, b.n);
    var r = i2c.decodeI2C(function(i){return a.volts[i];},
                          function(i){return b.volts[i];}, 0, n, info.srate, {});
    var text;
    var d = ds.decodeDS248x(r, {}); text = rep.ds248xReport(r, d);
    notify.update(toast, {render:
        "SDA=CH" + SDA_CH + " SCL=CH" + SCL_CH + "  " + (n/1e6).toFixed(2) +
        " Mpts @ " + (info.srate/1e9).toFixed(2) + " GSa/s\n\n" + text, autoClose:false});
} catch(e) {
    notify.update(toast, {render:"decode failed: " + e.message, autoClose:8000, type:"error"});
} finally {
    connection.command(":WAVeform:FORMat BYTE");
    connection.release();
}
